-- =====================================================================
-- Portfolio schema.
--
-- The content tables below hold the editable (draft) state of the site.
-- Visitors never read them directly: publishing writes an immutable
-- snapshot to portfolio_publication, and the public API serves only the
-- latest snapshot.
--
-- Conventions
--   * UUID primary keys, generated by the application.
--   * created_at / updated_at audit timestamps (UTC), version for
--     optimistic locking.
--   * Single-row tables carry singleton_key = 1 with a unique check.
--   * List items carry display_order and visible (publish / unpublish).
-- =====================================================================

-- ---------------------------------------------------------------------
-- Administrators (no rows are created here; see the authentication batch)
-- ---------------------------------------------------------------------
CREATE TABLE admin_user (
    id                    uuid         PRIMARY KEY,
    email                 varchar(254) NOT NULL,
    display_name          varchar(80)  NOT NULL,
    password_hash         varchar(100) NOT NULL,
    role                  varchar(20)  NOT NULL DEFAULT 'ADMIN',
    enabled               boolean      NOT NULL DEFAULT true,
    failed_login_attempts integer      NOT NULL DEFAULT 0,
    locked_until          timestamptz,
    last_login_at         timestamptz,
    created_at            timestamptz  NOT NULL DEFAULT now(),
    updated_at            timestamptz  NOT NULL DEFAULT now(),
    version               bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_admin_user_role CHECK (role IN ('ADMIN')),
    CONSTRAINT ck_admin_user_failed_attempts CHECK (failed_login_attempts >= 0)
);
CREATE UNIQUE INDEX ux_admin_user_email ON admin_user (lower(email));

-- ---------------------------------------------------------------------
-- Uploaded or externally hosted files (images, resume)
-- ---------------------------------------------------------------------
CREATE TABLE portfolio_asset (
    id                uuid          PRIMARY KEY,
    kind              varchar(20)   NOT NULL,
    storage_type      varchar(20)   NOT NULL,
    url               varchar(1000),
    storage_key       varchar(300),
    original_filename varchar(255)  NOT NULL,
    content_type      varchar(100)  NOT NULL,
    size_bytes        bigint,
    sha256            varchar(64),
    width             integer,
    height            integer,
    alt_text          varchar(200),
    created_at        timestamptz   NOT NULL DEFAULT now(),
    updated_at        timestamptz   NOT NULL DEFAULT now(),
    version           bigint        NOT NULL DEFAULT 0,
    CONSTRAINT ck_asset_kind CHECK (kind IN ('IMAGE', 'DOCUMENT')),
    CONSTRAINT ck_asset_storage_type CHECK (storage_type IN ('EXTERNAL', 'LOCAL')),
    CONSTRAINT ck_asset_location CHECK (
        (storage_type = 'EXTERNAL' AND url IS NOT NULL) OR
        (storage_type = 'LOCAL' AND storage_key IS NOT NULL)
    ),
    CONSTRAINT ck_asset_size CHECK (size_bytes IS NULL OR size_bytes >= 0)
);
CREATE UNIQUE INDEX ux_asset_storage_key ON portfolio_asset (storage_key) WHERE storage_key IS NOT NULL;

-- ---------------------------------------------------------------------
-- Profile (single row)
-- ---------------------------------------------------------------------
CREATE TABLE portfolio_profile (
    id                 uuid         PRIMARY KEY,
    singleton_key      integer      NOT NULL DEFAULT 1,
    full_name          varchar(120) NOT NULL,
    preferred_name     varchar(60)  NOT NULL,
    title              varchar(160) NOT NULL,
    location           varchar(120) NOT NULL,
    photo_asset_id     uuid REFERENCES portfolio_asset (id) ON DELETE SET NULL,
    photo_alt          varchar(200) NOT NULL,
    resume_asset_id    uuid REFERENCES portfolio_asset (id) ON DELETE SET NULL,
    public_email       varchar(254),
    available          boolean      NOT NULL DEFAULT true,
    availability_label varchar(120) NOT NULL,
    github_username    varchar(39),
    copyright_text     varchar(200) NOT NULL,
    footer_note        varchar(200) NOT NULL,
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    version            bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_profile_singleton UNIQUE (singleton_key),
    CONSTRAINT ck_profile_singleton CHECK (singleton_key = 1)
);
CREATE INDEX ix_profile_photo_asset ON portfolio_profile (photo_asset_id);
CREATE INDEX ix_profile_resume_asset ON portfolio_profile (resume_asset_id);

-- ---------------------------------------------------------------------
-- Hero (single row)
-- ---------------------------------------------------------------------
CREATE TABLE hero_content (
    id                  uuid         PRIMARY KEY,
    singleton_key       integer      NOT NULL DEFAULT 1,
    greeting            varchar(120) NOT NULL,
    role                varchar(120) NOT NULL,
    tagline             varchar(300) NOT NULL,
    primary_cta_label   varchar(60)  NOT NULL,
    primary_cta_href    varchar(500) NOT NULL,
    secondary_cta_label varchar(60)  NOT NULL,
    secondary_cta_href  varchar(500) NOT NULL,
    resume_label        varchar(60)  NOT NULL,
    focus_label         varchar(60)  NOT NULL,
    created_at          timestamptz  NOT NULL DEFAULT now(),
    updated_at          timestamptz  NOT NULL DEFAULT now(),
    version             bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_hero_singleton UNIQUE (singleton_key),
    CONSTRAINT ck_hero_singleton CHECK (singleton_key = 1)
);

CREATE TABLE hero_focus_area (
    hero_id  uuid         NOT NULL REFERENCES hero_content (id) ON DELETE CASCADE,
    position integer      NOT NULL,
    label    varchar(120) NOT NULL,
    PRIMARY KEY (hero_id, position)
);

-- ---------------------------------------------------------------------
-- About (single row with ordered child lists)
-- ---------------------------------------------------------------------
CREATE TABLE about_content (
    id               uuid         PRIMARY KEY,
    singleton_key    integer      NOT NULL DEFAULT 1,
    approach_heading varchar(120) NOT NULL,
    created_at       timestamptz  NOT NULL DEFAULT now(),
    updated_at       timestamptz  NOT NULL DEFAULT now(),
    version          bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_about_singleton UNIQUE (singleton_key),
    CONSTRAINT ck_about_singleton CHECK (singleton_key = 1)
);

CREATE TABLE about_paragraph (
    about_id uuid    NOT NULL REFERENCES about_content (id) ON DELETE CASCADE,
    position integer NOT NULL,
    body     text    NOT NULL,
    PRIMARY KEY (about_id, position),
    CONSTRAINT ck_about_paragraph_length CHECK (char_length(body) <= 2000)
);

CREATE TABLE about_fact (
    about_id uuid         NOT NULL REFERENCES about_content (id) ON DELETE CASCADE,
    position integer      NOT NULL,
    label    varchar(60)  NOT NULL,
    value    varchar(120) NOT NULL,
    PRIMARY KEY (about_id, position)
);

CREATE TABLE about_approach_step (
    about_id    uuid         NOT NULL REFERENCES about_content (id) ON DELETE CASCADE,
    position    integer      NOT NULL,
    step_label  varchar(10)  NOT NULL,
    title       varchar(80)  NOT NULL,
    description varchar(300) NOT NULL,
    PRIMARY KEY (about_id, position)
);

-- ---------------------------------------------------------------------
-- Section headings, navigation labels and section visibility
-- ---------------------------------------------------------------------
CREATE TABLE portfolio_section (
    id            uuid         PRIMARY KEY,
    section_key   varchar(20)  NOT NULL,
    nav_label     varchar(40)  NOT NULL,
    eyebrow       varchar(80)  NOT NULL,
    heading       varchar(160) NOT NULL,
    intro         varchar(500),
    visible       boolean      NOT NULL DEFAULT true,
    display_order integer      NOT NULL,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_section_key UNIQUE (section_key),
    CONSTRAINT ck_section_key CHECK (section_key IN ('ABOUT', 'SKILLS', 'PROJECTS', 'JOURNEY', 'EDUCATION', 'GITHUB', 'CONTACT'))
);
CREATE INDEX ix_section_order ON portfolio_section (display_order);

-- Section-specific copy, e.g. the contact form heading.
CREATE TABLE portfolio_section_setting (
    section_id    uuid         NOT NULL REFERENCES portfolio_section (id) ON DELETE CASCADE,
    setting_key   varchar(60)  NOT NULL,
    setting_value varchar(500) NOT NULL,
    PRIMARY KEY (section_id, setting_key)
);

-- ---------------------------------------------------------------------
-- Skills
-- ---------------------------------------------------------------------
CREATE TABLE skill_category (
    id            uuid         PRIMARY KEY,
    title         varchar(80)  NOT NULL,
    icon          varchar(20)  NOT NULL,
    description   varchar(200) NOT NULL,
    visible       boolean      NOT NULL DEFAULT true,
    display_order integer      NOT NULL,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_skill_category_icon CHECK (icon IN ('CODE', 'SERVER', 'DATABASE', 'NETWORK', 'TOOLS'))
);
CREATE INDEX ix_skill_category_order ON skill_category (display_order);

CREATE TABLE skill (
    id            uuid        PRIMARY KEY,
    category_id   uuid        NOT NULL REFERENCES skill_category (id) ON DELETE CASCADE,
    name          varchar(80) NOT NULL,
    visible       boolean     NOT NULL DEFAULT true,
    display_order integer     NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    version       bigint      NOT NULL DEFAULT 0,
    CONSTRAINT ux_skill_category_name UNIQUE (category_id, name)
);
CREATE INDEX ix_skill_category_order_idx ON skill (category_id, display_order);

-- ---------------------------------------------------------------------
-- Projects
-- ---------------------------------------------------------------------
CREATE TABLE project (
    id             uuid         PRIMARY KEY,
    slug           varchar(120) NOT NULL,
    name           varchar(160) NOT NULL,
    summary        varchar(300) NOT NULL,
    description    text         NOT NULL,
    image_asset_id uuid REFERENCES portfolio_asset (id) ON DELETE SET NULL,
    image_alt      varchar(200) NOT NULL,
    status         varchar(20)  NOT NULL,
    repo_url       varchar(500),
    demo_url       varchar(500),
    featured       boolean      NOT NULL DEFAULT false,
    visible        boolean      NOT NULL DEFAULT true,
    display_order  integer      NOT NULL,
    created_at     timestamptz  NOT NULL DEFAULT now(),
    updated_at     timestamptz  NOT NULL DEFAULT now(),
    version        bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_project_slug UNIQUE (slug),
    CONSTRAINT ck_project_slug CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT ck_project_status CHECK (status IN ('IN_DEVELOPMENT', 'COMPLETED', 'PLANNED')),
    CONSTRAINT ck_project_description_length CHECK (char_length(description) <= 5000)
);
CREATE INDEX ix_project_order ON project (visible, display_order);
CREATE INDEX ix_project_image_asset ON project (image_asset_id);

CREATE TABLE project_highlight (
    project_id uuid         NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    position   integer      NOT NULL,
    text       varchar(300) NOT NULL,
    PRIMARY KEY (project_id, position)
);

CREATE TABLE project_tag (
    project_id uuid        NOT NULL REFERENCES project (id) ON DELETE CASCADE,
    position   integer     NOT NULL,
    tag        varchar(60) NOT NULL,
    PRIMARY KEY (project_id, position)
);

-- ---------------------------------------------------------------------
-- Professional journey (experience)
-- ---------------------------------------------------------------------
CREATE TABLE experience (
    id            uuid         PRIMARY KEY,
    period_label  varchar(40)  NOT NULL,
    title         varchar(160) NOT NULL,
    organisation  varchar(160),
    description   text         NOT NULL,
    start_date    date,
    end_date      date,
    visible       boolean      NOT NULL DEFAULT true,
    display_order integer      NOT NULL,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_experience_dates CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date),
    CONSTRAINT ck_experience_description_length CHECK (char_length(description) <= 2000)
);
CREATE INDEX ix_experience_order ON experience (visible, display_order);

-- ---------------------------------------------------------------------
-- Education
-- ---------------------------------------------------------------------
CREATE TABLE education (
    id             uuid         PRIMARY KEY,
    degree         varchar(160) NOT NULL,
    field_of_study varchar(200) NOT NULL,
    institution    varchar(200),
    period_label   varchar(60)  NOT NULL,
    description    text         NOT NULL,
    visible        boolean      NOT NULL DEFAULT true,
    display_order  integer      NOT NULL,
    created_at     timestamptz  NOT NULL DEFAULT now(),
    updated_at     timestamptz  NOT NULL DEFAULT now(),
    version        bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_education_description_length CHECK (char_length(description) <= 2000)
);
CREATE INDEX ix_education_order ON education (visible, display_order);

-- ---------------------------------------------------------------------
-- Social links
-- ---------------------------------------------------------------------
CREATE TABLE social_link (
    id            uuid         PRIMARY KEY,
    platform      varchar(20)  NOT NULL,
    label         varchar(60)  NOT NULL,
    url           varchar(500),
    visible       boolean      NOT NULL DEFAULT true,
    display_order integer      NOT NULL,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_social_platform CHECK (platform IN ('GITHUB', 'LINKEDIN', 'EMAIL', 'WEBSITE'))
);
CREATE INDEX ix_social_link_order ON social_link (visible, display_order);

-- ---------------------------------------------------------------------
-- Appearance and SEO (single rows)
-- ---------------------------------------------------------------------
CREATE TABLE portfolio_appearance (
    id                 uuid        PRIMARY KEY,
    singleton_key      integer     NOT NULL DEFAULT 1,
    hero_scene_enabled boolean     NOT NULL DEFAULT true,
    motion_enabled     boolean     NOT NULL DEFAULT true,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    version            bigint      NOT NULL DEFAULT 0,
    CONSTRAINT ux_appearance_singleton UNIQUE (singleton_key),
    CONSTRAINT ck_appearance_singleton CHECK (singleton_key = 1)
);

CREATE TABLE seo_settings (
    id                uuid         PRIMARY KEY,
    singleton_key     integer      NOT NULL DEFAULT 1,
    meta_title        varchar(120) NOT NULL,
    meta_description  varchar(300) NOT NULL,
    canonical_url     varchar(500),
    og_image_asset_id uuid REFERENCES portfolio_asset (id) ON DELETE SET NULL,
    allow_indexing    boolean      NOT NULL DEFAULT true,
    created_at        timestamptz  NOT NULL DEFAULT now(),
    updated_at        timestamptz  NOT NULL DEFAULT now(),
    version           bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ux_seo_singleton UNIQUE (singleton_key),
    CONSTRAINT ck_seo_singleton CHECK (singleton_key = 1)
);

-- ---------------------------------------------------------------------
-- Contact messages
-- ---------------------------------------------------------------------
CREATE TABLE contact_message (
    id         uuid         PRIMARY KEY,
    name       varchar(80)  NOT NULL,
    email      varchar(254) NOT NULL,
    subject    varchar(120) NOT NULL,
    message    text         NOT NULL,
    status     varchar(20)  NOT NULL DEFAULT 'NEW',
    ip_hash    varchar(64),
    user_agent varchar(300),
    read_at    timestamptz,
    created_at timestamptz  NOT NULL DEFAULT now(),
    updated_at timestamptz  NOT NULL DEFAULT now(),
    version    bigint       NOT NULL DEFAULT 0,
    CONSTRAINT ck_contact_status CHECK (status IN ('NEW', 'READ', 'ARCHIVED')),
    CONSTRAINT ck_contact_message_length CHECK (char_length(message) BETWEEN 1 AND 2000)
);
CREATE INDEX ix_contact_message_status_created ON contact_message (status, created_at DESC);
CREATE INDEX ix_contact_message_created ON contact_message (created_at DESC);

-- ---------------------------------------------------------------------
-- Published snapshots (append-only)
-- ---------------------------------------------------------------------
CREATE TABLE portfolio_publication (
    id             uuid        PRIMARY KEY,
    version_number integer     NOT NULL,
    schema_version integer     NOT NULL,
    snapshot       jsonb       NOT NULL,
    note           varchar(200),
    published_by   uuid REFERENCES admin_user (id) ON DELETE SET NULL,
    published_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ux_publication_version UNIQUE (version_number),
    CONSTRAINT ck_publication_version CHECK (version_number > 0)
);
